  margin-top: 0;
}

.md-preview > :last-child {
  margin-bottom: 0;
}

.md-preview h1,
.md-preview h2,
.md-preview h3,
.md-preview h4,
.md-preview h5,
.md-preview h6 {
  margin: 1.2em 0 0.5em;
  line-height: 1.25;
  font-weight: 600;
}

.md-preview h1 {
  font-size: 1.75em;
}

.md-preview h2 {
  font-size: 1.4em;
  padding-bottom: 0.2em;
  border-bottom: 1px solid var(--g-color-line-generic);
}

.md-preview h3 {
  font-size: 1.2em;
}

.md-preview h4,
.md-preview h5,
.md-preview h6 {
  font-size: 1em;
}

.md-preview p,
.md-preview ul,
.md-preview ol,
.md-preview blockquote,
.md-preview pre,
.md-preview table {
  margin: 0 0 0.9em;
}

.md-preview ul,
.md-preview ol {
  padding-left: 1.6em;
}

.md-preview li + li {
  margin-top: 0.25em;
}

.md-preview a {
  color: var(--g-color-text-link);
}

.md-preview blockquote {
  padding: 0 1em;
  color: var(--g-color-text-secondary);
  border-left: 3px solid var(--g-color-line-generic-hover);
}

.md-preview code {
  padding: 0.15em 0.35em;
  border-radius: 4px;
  background: var(--g-color-base-neutral-light);
  font-family: var(--g-font-family-monospace);
  font-size: 0.9em;
}

.md-preview pre {
  padding: 12px;
  overflow-x: auto;
  border-radius: var(--g-border-radius-m);
  background: var(--g-color-base-neutral-light);
}

.md-preview pre code {
  padding: 0;
  background: none;
  font-size: 0.9em;
}

.md-preview table {
  display: block;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
}

.md-preview th,
.md-preview td {
  padding: 6px 10px;
  border: 1px solid var(--g-color-line-generic);
  text-align: left;
}

.md-preview th {
  background: var(--g-color-base-neutral-light);
  font-weight: 600;
}

.md-preview hr {
  margin: 1.2em 0;
  border: none;
  border-top: 1px solid var(--g-color-line-generic);
}

.md-preview img {
  max-width: 100%;
  height: auto;
}

.md-preview input[type='checkbox'] {
  margin-right: 0.4em;
}

